from common21 import Q,R,load,dump
import csv,math,datetime,collections
assert load(Q/'state/round_status.json')['status']=='ALL_EXPERIMENTS_COMPLETE_AWAIT_ANALYSIS'
rows=load(Q/'results/hardware/route_all.json');assert len(rows)==12
out=[];mechanism=[]
for c in load(Q/'configs/plan.json')['cases']:
 n=c['name'];rr={r['method']:r for r in rows if r['case']==n};baseline=[rr[m]for m in ['quadol_wce','serial_then_quadol']];best=min(baseline,key=lambda r:(r['LUT'],r['SSE']));main=rr['state_window'];quality=rr['quality_window'];qs=load(Q/f'state/{n}_quality_window_state.json')
 gain=lambda a,b:100*(a-b)/a if a else (0 if b==0 else None)
 out.append(dict(case=n,compensation=c['compensation'],seed_WCE=c['seed_budget'],best_baseline=best['method'],LUT={m:r['LUT']for m,r in rr.items()},FF={m:r['FF']for m,r in rr.items()},CARRY4={m:r['CARRY4']for m,r in rr.items()},WCE={m:r['WCE']for m,r in rr.items()},MAE={m:r['MAE']for m,r in rr.items()},RMSE={m:math.sqrt(r['MSE'])for m,r in rr.items()},SSE={m:r['SSE']for m,r in rr.items()},bias={m:r['bias']for m,r in rr.items()},WNS_ns={m:r['WNS_ns']for m,r in rr.items()},timing={m:r['pass_registered_clock']for m,r in rr.items()},main_LUT_gain_vs_best_baseline_pct=gain(best['LUT'],main['LUT']),quality_LUT_gain_vs_best_baseline_pct=gain(best['LUT'],quality['LUT']),quality_RMSE_improvement_vs_main_pct=gain(math.sqrt(main['MSE']),math.sqrt(quality['MSE'])),quality_LUT_change_vs_main=quality['LUT']-main['LUT'],quality_changes=qs['quality_changes'],window_status_counts=dict(collections.Counter(h['status']for h in qs['history'])),quality_dominates_main=quality['LUT']<=main['LUT']and quality['SSE']<=main['SSE']and(quality['LUT']<main['LUT']or quality['SSE']<main['SSE']),quality_dominated_by_any_baseline=any(b['LUT']<=quality['LUT']and b['SSE']<=quality['SSE']and(b['LUT']<quality['LUT']or b['SSE']<quality['SSE'])for b in baseline)))
 for h in qs['history']:mechanism.append(dict(case=n,pair=h['pair'],status=h['status'],solver_status=h['solver']['status'],before_SSE=h['solver']['incumbent_cost'],after_SSE=h['solver'].get('cost'),variables=h['solver'].get('variables'),context=h['context']))
