 fields=['case','method','LUT','FF','CARRY4','WCE','MAE','MSE','SSE','bias','WNS_ns','WHS_ns','pass_registered_clock'];writer=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');writer.writeheader();writer.writerows(rows)
